<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Role\Domain;

use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Holder\RoleUidAttributeHolder;
use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Holder\RoleNameAttributeHolder;
use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Holder\RoleRelyingPartyAttributeHolder;
use Civi\Lughauth\Features\Access\Role\Domain\ValueObject\Holder\RoleVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class RoleAttributes
{
    use RoleUidAttributeHolder;
    use RoleNameAttributeHolder;
    use RoleRelyingPartyAttributeHolder;
    use RoleVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'name' => 'unsetName',
      'relyingParty' => 'unsetRelyingParty',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): Role
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $name = $this->nameTryBuildInitial($errors);
        $relyingParty = $this->relyingPartyTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($name !== null);
        return new Role(
            uid: $uid,
            name: $name,
            relyingParty: $relyingParty,
            version: $version,
        );
    }
    public function withAssertedRules(): RoleAttributes
    {
        $value = new RoleAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedNameRules($value, $errorsList);
        $this->withAssertedRelyingPartyRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): RoleAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultName();
        $this->withDefaultRelyingParty();
        $this->withDefaultVersion();
        return $this;
    }
}
